#include <cstring>
using namespace std;

int h, n;
vector<int> b;
vector<int> dp; // Changed dp to a vector to handle dynamic sizing

int dfs(int i = 1, int bit = 0) {
    if (i == h) return 0;
    bit |= b[i];
    int state = (i << 3) | bit; // Encode the state using bit manipulation
    if (state >= dp.size()) return 0; // Prevent out of bounds access
    if (dp[state] != -1) return dp[state]; // Improved clarity in checking state
    dp[state] = 0;

    // Streamlined recursion conditions for clarity
    if (bit == 0) dp[state] = max(dp[state], dfs(i + 1, 0b111) + 2);
    else if ((bit & 0b110) == 0) dp[state] = max(dp[state], dfs(i + 1, 0b110) + 1);
    else if ((bit & 0b011) == 0) dp[state] = max(dp[state], dfs(i + 1, 0b011) + 1);

    dp[state] = max(dp[state], dfs(i + 1, 0)); // Check for no bits set
    return dp[state];
}

int main() {
    cin >> h >> n; // Efficient input handling
    b.assign(h + 1, 0);
    dp.resize((h + 1) << 3); // Dynamically sized dp vector
    memset(dp.data(), -1, dp.size() * sizeof(int)); // Correctly memset the vector
